/**
 * ReferenceLibraryPage — JM DIE/TRIBAL + WIKI corpus browser.
 *
 * Quebec /goal frontend (U-Q-REFERENCE-LIBRARY-PAGE).
 *
 * Surfaces the 80-PDF JM Die test-shop reference library using the
 * PrismResourceCard primitive. No backend dependency at runtime — the
 * catalog is statically generated by scripts/generate-reference-library-catalog.mjs
 * and committed alongside this page.
 *
 * Design — Calculator Studio language:
 *   - PrismGlowCard frame per domain section (color per domain semantic)
 *   - PrismChip for kind + status tags
 *   - PrismResourceCard tile per PDF (kind/domain/size shown)
 *   - Domain filter pills at the top (single-select)
 *   - Search box (filename + title fuzzy)
 *
 * Wired in App.tsx as `<Route path="reference-library">`. Lazy-loaded via the
 * existing lazyNamed() pattern.
 */

import { useMemo, useState } from "react";
import {
  REFERENCE_LIBRARY_CATALOG,
  REFERENCE_LIBRARY_CORPUS,
  REFERENCE_LIBRARY_DOMAINS,
  REFERENCE_LIBRARY_GENERATED_AT,
  type ReferenceLibraryEntry,
} from "../data/referenceLibraryCatalog";
import { PrismChip, PrismGlowCard, PrismResourceCard } from "../components/prism";

const DOMAIN_LABELS: Record<string, { label: string; tone: "cyan" | "amber" | "emerald" | "red" | "violet" }> = {
  mill: { label: "Mill", tone: "cyan" },
  lathe: { label: "Lathe", tone: "amber" },
  wedm: { label: "Wire EDM", tone: "violet" },
  cad: { label: "CAD", tone: "emerald" },
  cam: { label: "CAM", tone: "cyan" },
  controller: { label: "Controller", tone: "violet" },
  gcode: { label: "G-Code", tone: "emerald" },
  "speeds-feeds": { label: "Speeds & Feeds", tone: "amber" },
  ops: { label: "Operations", tone: "cyan" },
  "5-axis": { label: "5-Axis", tone: "violet" },
  tooling: { label: "Tooling", tone: "amber" },
  cs: { label: "Computer Science", tone: "emerald" },
  general: { label: "General", tone: "cyan" },
};

function labelFor(domain: string): { label: string; tone: "cyan" | "amber" | "emerald" | "red" | "violet" } {
  return DOMAIN_LABELS[domain] ?? { label: domain, tone: "cyan" };
}

export function ReferenceLibraryPage() {
  const [filterDomain, setFilterDomain] = useState<string | null>(null);
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return REFERENCE_LIBRARY_CATALOG.filter((e) => {
      if (filterDomain && e.domain !== filterDomain) return false;
      if (q && !e.title.toLowerCase().includes(q) && !e.filename.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [filterDomain, search]);

  const byDomain = useMemo(() => {
    const map = new Map<string, ReferenceLibraryEntry[]>();
    for (const e of filtered) {
      const arr = map.get(e.domain) ?? [];
      arr.push(e);
      map.set(e.domain, arr);
    }
    return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  }, [filtered]);

  const totalCount = REFERENCE_LIBRARY_CATALOG.length;
  const visibleCount = filtered.length;

  return (
    <main
      className="min-h-screen px-6 py-8"
      style={{ background: "rgba(2,6,23,0.78)", color: "rgb(226,232,240)" }}
    >
      <header className="mb-8 max-w-6xl mx-auto">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">Reference Library</h1>
            <p className="text-sm opacity-70 mt-1">
              {REFERENCE_LIBRARY_CORPUS} · {totalCount} PDFs · generated{" "}
              {new Date(REFERENCE_LIBRARY_GENERATED_AT).toLocaleDateString()}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <PrismChip tone="emerald">{visibleCount} shown</PrismChip>
            {filterDomain ? <PrismChip tone={labelFor(filterDomain).tone}>{labelFor(filterDomain).label}</PrismChip> : null}
          </div>
        </div>
      </header>

      <section className="mb-6 max-w-6xl mx-auto">
        <div className="flex flex-wrap gap-2 mb-3">
          <button
            type="button"
            onClick={() => setFilterDomain(null)}
            className={`prism-chip ${filterDomain === null ? "prism-glow-cyan" : ""}`}
            style={{ cursor: "pointer", border: "1px solid rgba(148,163,184,0.18)" }}
          >
            All ({totalCount})
          </button>
          {REFERENCE_LIBRARY_DOMAINS.map((domain) => {
            const meta = labelFor(domain);
            const count = REFERENCE_LIBRARY_CATALOG.filter((e) => e.domain === domain).length;
            const active = filterDomain === domain;
            return (
              <button
                key={domain}
                type="button"
                onClick={() => setFilterDomain(active ? null : domain)}
                className={`prism-chip ${active ? `prism-glow-${meta.tone}` : ""}`}
                style={{ cursor: "pointer", border: "1px solid rgba(148,163,184,0.18)" }}
              >
                {meta.label} ({count})
              </button>
            );
          })}
        </div>

        <input
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search title or filename…"
          aria-label="Filter reference library"
          className="w-full max-w-xl px-3 py-2 rounded-lg"
          style={{
            background: "rgba(8,18,33,0.94)",
            border: "1px solid rgba(148,163,184,0.18)",
            color: "rgb(226,232,240)",
          }}
        />
      </section>

      <section className="max-w-6xl mx-auto space-y-6">
        {byDomain.length === 0 ? (
          <PrismGlowCard tone="cyan" className="p-6 text-center">
            <p className="opacity-80">No entries match the current filter.</p>
          </PrismGlowCard>
        ) : (
          byDomain.map(([domain, entries]) => {
            const meta = labelFor(domain);
            return (
              <PrismGlowCard key={domain} color={meta.tone} className="p-5">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-semibold">{meta.label}</h2>
                  <PrismChip tone={meta.tone}>{entries.length}</PrismChip>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                  {entries.map((entry) => (
                    <PrismResourceCard
                      key={entry.slug}
                      title={entry.title}
                      subtitle={entry.filename}
                      kind={entry.kind}
                      status="ready"
                      meta={`${entry.sizeLabel} · ${meta.label}`}
                      color={meta.tone}
                      href={`/reference-library/${entry.slug}`}
                    />
                  ))}
                </div>
              </PrismGlowCard>
            );
          })
        )}
      </section>

      <footer className="max-w-6xl mx-auto mt-12 pt-6 text-xs opacity-50" style={{ borderTop: "1px solid rgba(148,163,184,0.12)" }}>
        Source: <code>{REFERENCE_LIBRARY_CORPUS}</code> · Regenerate with{" "}
        <code>node scripts/generate-reference-library-catalog.mjs</code>
      </footer>
    </main>
  );
}

export default ReferenceLibraryPage;
